const AGENT_IDS = ['project-manager', 'sales', 'marketing', 'investment', 'bookkeeping'];
const FREQUENCIES = ['daily', 'weekdays', 'weekly', 'monthly', 'once'];
// Ten is not a technical limit. It is the point past which nobody remembers
// what their agent is doing overnight, and every one of these costs money.
const MAX_SCHEDULES = 10;

// --- working out when a schedule next comes round --------------------------
// The clock inside this agent is UTC unless somebody set GENERIC_TIMEZONE, and
// in the cloud it usually is. So "8am" has to be pinned to a named zone or a
// Melbourne morning fires at six in the evening. Every schedule carries its own
// timezone, and everything below converts between that zone's wall clock and a
// real instant.
const DAY_NAMES = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

const zoneIsReal = (zone) => {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: zone });
    return true;
  } catch {
    return false;
  }
};

const zoneParts = (instant, zone) => {
  const read = {};
  for (const part of new Intl.DateTimeFormat('en-US', {
    timeZone: zone, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(instant)) {
    read[part.type] = part.value;
  }
  return {
    year: Number(read.year), month: Number(read.month), day: Number(read.day),
    // Some environments render midnight as hour 24 rather than 0.
    hour: Number(read.hour) % 24, minute: Number(read.minute), second: Number(read.second),
  };
};

// How far that zone sits from UTC at that moment, daylight saving included.
const zoneOffsetMinutes = (instant, zone) => {
  const at = zoneParts(instant, zone);
  return (Date.UTC(at.year, at.month - 1, at.day, at.hour, at.minute, at.second) - instant.getTime()) / 60000;
};

// A wall-clock time in that zone, back to a real instant. The offset depends on
// the answer, so it is applied twice: once against a guess, then again against
// the offset that guess actually landed in. That second pass is what keeps the
// hour right on the two days a year the clocks move.
const instantAt = (year, month, day, hour, minute, zone) => {
  const wall = Date.UTC(year, month - 1, day, hour, minute, 0);
  const guess = new Date(wall - zoneOffsetMinutes(new Date(wall), zone) * 60000);
  return new Date(wall - zoneOffsetMinutes(guess, zone) * 60000);
};

// The first moment strictly after `after` that matches the rule, or null.
const nextRunAfter = (rule, after) => {
  const zone = rule.timezone;
  if (!zoneIsReal(zone)) return null;
  const clock = String(rule.timeOfDay ?? '').split(':').map(Number);
  const hour = clock[0];
  const minute = clock[1];
  if (!Number.isInteger(hour) || !Number.isInteger(minute)) return null;

  if (rule.frequency === 'once') {
    if (rule.onDate) {
      const parts = String(rule.onDate).split('-').map(Number);
      const once = instantAt(parts[0], parts[1], parts[2], hour, minute, zone);
      return once.getTime() > after.getTime() ? once : null;
    }
  }

  const from = zoneParts(after, zone);
  for (let step = 0; step <= 400; step += 1) {
    // Adding to the day number rolls months and years over on its own.
    const day = new Date(Date.UTC(from.year, from.month - 1, from.day + step));
    const year = day.getUTCFullYear();
    const month = day.getUTCMonth() + 1;
    const date = day.getUTCDate();
    const weekday = DAY_NAMES[day.getUTCDay()];
    if (rule.frequency === 'weekdays' && (weekday === 'saturday' || weekday === 'sunday')) continue;
    if (rule.frequency === 'weekly' && weekday !== rule.dayOfWeek) continue;
    if (rule.frequency === 'monthly' && date !== Number(rule.dayOfMonth)) continue;
    const candidate = instantAt(year, month, date, hour, minute, zone);
    if (candidate.getTime() > after.getTime()) return candidate;
  }
  return null;
};

// What the agent reads back to the owner, in their own timezone.
const inWords = (instant, zone) => {
  if (!instant || !zoneIsReal(zone)) return '';
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: zone, weekday: 'short', day: 'numeric', month: 'short',
    year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true,
  }).format(instant) + ' (' + zone + ')';
};

const clockInWords = (timeOfDay) => {
  const clock = String(timeOfDay ?? '').split(':').map(Number);
  const hour = clock[0];
  const minute = clock[1];
  if (!Number.isInteger(hour) || !Number.isInteger(minute)) return String(timeOfDay ?? '');
  const suffix = hour < 12 ? 'am' : 'pm';
  const shown = hour % 12 === 0 ? 12 : hour % 12;
  return shown + ':' + String(minute).padStart(2, '0') + ' ' + suffix;
};

const patternInWords = (rule) => {
  const at = 'at ' + clockInWords(rule.timeOfDay);
  if (rule.frequency === 'daily') return 'every day ' + at;
  if (rule.frequency === 'weekdays') return 'every weekday ' + at;
  if (rule.frequency === 'weekly') {
    const day = String(rule.dayOfWeek ?? '');
    return 'every ' + day.charAt(0).toUpperCase() + day.slice(1) + ' ' + at;
  }
  if (rule.frequency === 'monthly') return 'on day ' + rule.dayOfMonth + ' of each month ' + at;
  return 'once, ' + at;
};


const input = $('Tool Input').first().json;
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && typeof row.scheduleId === 'string' && row.scheduleId !== '');

const text = (value, limit) => {
  const raw = typeof value === 'string' ? value.trim() : '';
  return raw.slice(0, limit ?? 200);
};
const normalise = (value) => String(value).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const sessionId = text(input.sessionId, 60);
const requestId = text(input.requestId, 60);
const proposedInput = {
  sessionId,
  requestId,
  scheduleId: text(input.scheduleId, 40),
  name: text(input.name, 80),
  instruction: text(input.instruction, 1200),
  agent: text(input.agent, 40),
  frequency: text(input.frequency, 20),
  time: text(input.time, 20),
  dayOfWeek: text(input.dayOfWeek, 20),
  dayOfMonth: text(input.dayOfMonth, 10),
  date: text(input.date, 20),
  timezone: text(input.timezone, 60),
};
const fail = (code, message) => ({ json: {
  valid: false, sessionId, requestId, proposedInput,
  response: { ok: false, error: { code, message } },
} });

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  return [fail('INVALID_SESSION', 'Saving a schedule needs a valid conversation and request ID.')];
}

const assumptions = [];

// --- what should run -------------------------------------------------------
// The instruction is sent to the agent later, on its own, with nobody watching.
// It has to read like something typed into the chat, not like a note to self.
const instruction = proposedInput.instruction;
if (instruction.length < 5) {
  return [fail('INSTRUCTION_REQUIRED', 'Ask the user what they want done at that time, then call this again with it written out the way they would type it into the chat. The agent reads only that sentence when the schedule fires; it cannot see this conversation.')];
}

// --- which agent runs it ---------------------------------------------------
// Tools are attached to one agent each, so a schedule pointed at the wrong one
// reaches an agent that politely says it has no such tool, every single day.
const AGENT_ALIASES = {
  pm: 'project-manager', projectmanager: 'project-manager', 'project-manger': 'project-manager',
  finance: 'bookkeeping', accounts: 'bookkeeping', accounting: 'bookkeeping', bookkeeper: 'bookkeeping',
  investor: 'investment', investments: 'investment', funding: 'investment',
  sale: 'sales', seller: 'sales', marketer: 'marketing', seo: 'marketing', research: 'marketing',
};
let agentId = proposedInput.agent.toLowerCase().replace(/[\s_]+/g, '-');
agentId = AGENT_ALIASES[agentId.replace(/-/g, '')] ?? AGENT_ALIASES[agentId] ?? agentId;
if (agentId === '') {
  agentId = 'project-manager';
  assumptions.push('your project manager runs it, because no other role was named');
}
if (!AGENT_IDS.includes(agentId)) {
  return [fail('AGENT_NOT_RECOGNISED', 'A schedule has to name which agent runs it: project-manager, sales, marketing, investment, or bookkeeping. Pick the one that owns the skill being scheduled, which is the same agent you would open in the chat to ask for it by hand.')];
}

// --- how often -------------------------------------------------------------
const FREQUENCY_ALIASES = {
  everyday: 'daily', day: 'daily', days: 'daily', eachday: 'daily', morning: 'daily',
  weekday: 'weekdays', workday: 'weekdays', workdays: 'weekdays', businessdays: 'weekdays',
  week: 'weekly', eachweek: 'weekly', everyweek: 'weekly',
  month: 'monthly', eachmonth: 'monthly', everymonth: 'monthly',
  oneoff: 'once', onetime: 'once', today: 'once', tomorrow: 'once',
};
let frequency = proposedInput.frequency.toLowerCase().replace(/[\s_-]+/g, '');
frequency = FREQUENCY_ALIASES[frequency] ?? frequency;
if (frequency === '') {
  frequency = 'daily';
  assumptions.push('it repeats every day');
}
if (!FREQUENCIES.includes(frequency)) {
  return [fail('FREQUENCY_NOT_RECOGNISED', 'A schedule repeats daily, on weekdays, weekly, monthly, or once. There is nothing smaller than a day on purpose: an hourly job against a metered API key gets expensive without anyone noticing.')];
}

// --- what time -------------------------------------------------------------
// A model passes on whatever the user said, so this reads "8am", "8:30 pm",
// "0800" and "17:30" rather than making the agent ask twice.
const parseTime = (value) => {
  const raw = String(value ?? '').trim().toLowerCase().replace(/\./g, '').replace(/\s+/g, '');
  if (raw === '') return null;
  if (raw === 'midnight') return '00:00';
  if (raw === 'noon' || raw === 'midday') return '12:00';
  const match = raw.match(/^([0-9]{1,2})(?::?([0-9]{2}))?(am|pm)?$/);
  if (!match) return null;
  let hour = Number(match[1]);
  const minute = match[2] === undefined ? 0 : Number(match[2]);
  if (minute > 59) return null;
  if (match[3] === 'am') {
    if (hour < 1 || hour > 12) return null;
    if (hour === 12) hour = 0;
  } else if (match[3] === 'pm') {
    if (hour < 1 || hour > 12) return null;
    if (hour !== 12) hour += 12;
  } else if (hour > 23) {
    return null;
  }
  return String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
};
const timeOfDay = parseTime(proposedInput.time);
if (timeOfDay === null) {
  return [fail('TIME_REQUIRED', 'Ask the user what time of day it should run, then call this again. Pass it exactly as they said it: "8am", "5:30pm" and "17:30" all read correctly.')];
}

// --- which day -------------------------------------------------------------
const parseDay = (value) => {
  const raw = String(value ?? '').trim().toLowerCase().replace(/s$/, '');
  if (raw.length < 3) return '';
  return DAY_NAMES.find((day) => day.slice(0, 3) === raw.slice(0, 3)) ?? '';
};
let dayOfWeek = '';
if (frequency === 'weekly') {
  dayOfWeek = parseDay(proposedInput.dayOfWeek);
  if (dayOfWeek === '') {
    dayOfWeek = 'monday';
    assumptions.push('the weekly run falls on a Monday');
  }
}
let dayOfMonth = 0;
if (frequency === 'monthly') {
  const asked = Number(String(proposedInput.dayOfMonth).replace(/[^0-9]/g, ''));
  if (Number.isInteger(asked) && asked >= 1 && asked <= 28) {
    dayOfMonth = asked;
  } else if (Number.isInteger(asked) && asked >= 29) {
    dayOfMonth = 28;
    assumptions.push('the monthly run falls on the 28th, because the 29th, 30th and 31st do not exist in every month');
  } else {
    dayOfMonth = 1;
    assumptions.push('the monthly run falls on the 1st');
  }
}
let onDate = '';
if (frequency === 'once' && /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(proposedInput.date)) {
  onDate = proposedInput.date;
}

// --- whose clock -----------------------------------------------------------
// Reading the container's own clock looked helpful and was not: it is the
// learner's timezone on their laptop and UTC in the cloud, so the same
// schedule meant two different times depending on where the agent happened to
// be running, and in the cloud 8am fired at six in the evening. A named
// default means a schedule means the same thing everywhere, and it is stated
// back to the user every time rather than assumed quietly.
const DEFAULT_TIMEZONE = 'Australia/Melbourne';
let timezone = proposedInput.timezone;
if (timezone === '') {
  timezone = DEFAULT_TIMEZONE;
  assumptions.push('the time means ' + DEFAULT_TIMEZONE + ' time, which is what this agent assumes when nobody has said where they are');
}
if (!zoneIsReal(timezone)) {
  return [fail('TIMEZONE_NOT_RECOGNISED', 'That is not a timezone this agent recognises. Pass a standard name such as Australia/Melbourne, Europe/London, or America/New_York.')];
}

// --- naming it -------------------------------------------------------------
let name = proposedInput.name;
if (name === '') {
  // Cutting on a full stop turns "research mlai.au" into "research mlai", so
  // this cuts on length and steps back to the last whole word.
  const flat = instruction.replace(/\s+/g, ' ').trim();
  name = flat.length <= 60 ? flat : flat.slice(0, 60).replace(/\s\S*$/, '');
  if (name === '') name = 'Scheduled work';
  assumptions.push('it is called "' + name + '"');
}

// The ID comes from the name, so asking for the same thing again changes the
// one schedule instead of quietly leaving two running side by side.
const fnv = (seed) => {
  let hash = 0x811c9dc5;
  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
};

const askedId = proposedInput.scheduleId;
let existing = null;
if (askedId !== '') {
  existing = rows.find((row) => row.scheduleId === askedId) ?? null;
  if (!existing) {
    return [fail('SCHEDULE_NOT_FOUND', 'There is no schedule with that ID. Call list_schedules to see what is saved and use an ID from that list, or leave the ID out to create a new one.')];
  }
} else {
  existing = rows.find((row) => normalise(row.name ?? '') === normalise(name)) ?? null;
}

let scheduleId = existing ? existing.scheduleId : '';
if (scheduleId === '') {
  let attempt = 0;
  do {
    scheduleId = 'sch-' + fnv(normalise(name) + (attempt === 0 ? '' : '#' + attempt));
    attempt += 1;
  } while (rows.some((row) => row.scheduleId === scheduleId) && attempt < 20);
}

const enabledCount = rows.filter((row) => String(row.enabled ?? '') === 'yes').length;
if (!existing && enabledCount >= MAX_SCHEDULES) {
  return [fail('TOO_MANY_SCHEDULES', 'This agent already has ' + MAX_SCHEDULES + ' schedules switched on, which is the limit. Ask the user which one to pause or delete first, then use update_schedule.')];
}

// --- when it next comes round ----------------------------------------------
const rule = { frequency, timeOfDay, dayOfWeek, dayOfMonth, onDate, timezone };
const now = new Date();
const nextRun = nextRunAfter(rule, now);
if (nextRun === null) {
  return [fail('TIME_ALREADY_PAST', frequency === 'once'
    ? 'That one-off time has already gone by. Ask the user for a date and time still ahead of them, and pass the date as YYYY-MM-DD.'
    : 'That combination of day and time never comes round. Check both and try again.')];
}

return [{ json: {
  valid: true,
  sessionId,
  requestId,
  proposedInput,
  scheduleId,
  name,
  instruction,
  agentId,
  frequency,
  timeOfDay,
  dayOfWeek,
  dayOfMonth,
  onDate,
  timezone,
  enabled: 'yes',
  createdAt: existing ? String(existing.createdAt ?? now.toISOString()) : now.toISOString(),
  nextRunAt: nextRun.toISOString(),
  lastRunAt: existing ? String(existing.lastRunAt ?? '') : '',
  lastStatus: existing ? String(existing.lastStatus ?? '') : '',
  lastSummary: existing ? String(existing.lastSummary ?? '') : '',
  runCount: existing ? Number(existing.runCount ?? 0) || 0 : 0,
  replaced: Boolean(existing),
  runsWhen: patternInWords(rule),
  nextRun: inWords(nextRun, timezone),
  assumptions,
  // Nothing here can see whether the trigger is published, and a schedule that
  // never fires looks exactly like one that has not come round yet. So while
  // nothing has ever run, say so every time.
  nothingHasEverRun: rows.every((row) => !(Number(row.runCount ?? 0) > 0)),
} }];

const plan = $('Validate And Plan').first().json;
const saved = $json.id !== undefined || $json.scheduleId === plan.scheduleId;

if (!saved) {
  return [{ json: { ...plan, response: { ok: false, error: {
    code: 'SAVE_FAILED',
    message: "The schedule could not be saved. If the '16 - SETUP - Scheduled Work Data' workflow has never been run, run it once in n8n and try again.",
  } } } }];
}

const notes = [];
if (plan.nothingHasEverRun) {
  notes.push("Nothing has run on a schedule here yet. Tell the user that the '79 - TRIGGER - Scheduled work' workflow has to be Published in n8n before anything fires, and that saving a schedule on its own does nothing.");
}
notes.push('A scheduled run happens with nobody watching, so it cannot answer a question or send a confirmation phrase. It can research, read and report; anything that needs the user to confirm a write will simply wait for them.');
notes.push('Its answer is saved, not delivered. Tell the user to ask you what their schedules have turned up, and you will read it back with list_schedules.');

return [{ json: { ...plan, response: {
  ok: true,
  saved: true,
  replaced: plan.replaced,
  schedule: {
    scheduleId: plan.scheduleId,
    name: plan.name,
    instruction: plan.instruction,
    agent: plan.agentId,
    runsWhen: plan.runsWhen,
    timezone: plan.timezone,
    nextRun: plan.nextRun,
  },
  assumptions: plan.assumptions,
  notes,
  message: (plan.replaced
    ? 'Updated the existing schedule rather than adding a second one. '
    : 'Saved. ')
    + 'Read back to the user what it will do, which agent runs it, when it next runs, and every assumption listed here, so they can correct anything you guessed.',
} } }];

const input = $('Validate And Plan').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'create_schedule',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').first().json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
